// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
// ---- End of helpers ----

const cfg = $('Set Configuration Params').first().json;
const problems = [];
const unset = (v) => !isEmail(v) || /@example\.com$/i.test(text(v));

if (!text(cfg.googleSheetId) || cfg.googleSheetId === 'YOUR_GOOGLE_SHEET_ID') {
  problems.push('googleSheetId: the part of your sheet URL between /d/ and /edit');
}
if (unset(cfg.staffEmail)) problems.push('staffEmail: your own address (in test mode every email goes here)');
if (unset(cfg.replyToEmail)) problems.push('replyToEmail: the address clients should reply to');
if (!/^https?:\/\//i.test(text(cfg.bookingPageUrl)) || /example\.com/i.test(text(cfg.bookingPageUrl))) {
  problems.push('bookingPageUrl: the page where clients book');
}
if (!text(cfg.businessName) || cfg.businessName === 'Your Business Name') problems.push('businessName');
// The stop alert reads staffEmail without running this node, so it has to be plain text.
const typed = (($('Set Configuration Params').params.assignments || {}).assignments || []).find((a) => a.name === 'staffEmail');
if (typed && String(typed.value).startsWith('=')) problems.push('staffEmail: type the address as plain text, not an expression');

for (const [k, min] of [['offersPerRound', 1], ['claimWindowHours', 0.25], ['maxOffersPerSlot', 1], ['minHoursNotice', 0], ['maxDaysAhead', 0]]) {
  if (!(Number(cfg[k]) >= min)) problems.push(`${k}: a number of at least ${min}`);
}
if (problems.length) {
  throw new Error(`Nothing was sent. Fill in Set Configuration Params:\n- ${problems.join('\n- ')}`);
}
return [{ json: { timezone: $now.zoneName } }];

// Google Sheets silently ignores values for columns it cannot find, so a typo in a header
// would lose the record of what was sent and cause repeat emails. Check before sending anything.
const REQUIRED = {"Bookings": ["Booking ID", "Service", "Appointment Date", "Appointment Time", "Status", "Waitlist Offered To", "Waitlist Offered At"], "Waitlist": ["Waitlist ID", "Client Name", "Client Email", "Service", "Earliest Date", "Latest Date", "Status", "Added At", "Offered Slot", "Offered At", "Offer Error"]};
const ranges = $input.first().json.valueRanges || [];
const problems = [];
for (const [tab, columns] of Object.entries(REQUIRED)) {
  const found = ranges.find((r) => String(r.range || '').replace(/'/g, '').startsWith(`${tab}!`));
  const headers = ((found && found.values && found.values[0]) || []).map((h) => String(h));
  for (const col of columns) {
    if (headers.includes(col)) continue;
    const near = headers.find((h) => h.trim().toLowerCase() === col.toLowerCase());
    problems.push(near !== undefined
      ? `${tab}: header "${near}" must be exactly "${col}"`
      : `${tab}: column "${col}" is missing`);
  }
}
if (problems.length) {
  throw new Error(`Nothing was sent. Fix row 1 of your sheet:\n- ${problems.join('\n- ')}`);
}
return [{ json: {} }];

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
const list = (v) => text(v).split(',').map((x) => x.trim()).filter(Boolean);
// IDs are matched exactly as Google Sheets displays them. When results are written back, the Sheets
// update looks the row up by its displayed text, so this is the value that finds the row again
// (a number formatted as 1,001.00 is read as 1001 but found as "1,001.00").
const DISPLAYED = {};
for (const r of $('Fetch Spreadsheet Data').first().json.valueRanges || []) {
  DISPLAYED[String(r.range || '').replace(/'/g, '').split('!')[0]] = r.values || [];
}
// Returns null when the row moved between the two reads (sorted, inserted or deleted in between):
// a text cell shows exactly the same text in both reads, so any difference means it is not the same row.
// Such a row is left for the next run instead of risking a write to someone else's row.
const shownKey = (tab, column, row) => {
  const values = DISPLAYED[tab] || [];
  const headers = values[0] || [];
  const line = values[(row.row_number || 0) - 1];
  if (!line) return null;
  for (const [col, v] of Object.entries(row)) {
    if (typeof v !== 'string' || v === '') continue;
    const at = headers.indexOf(col);
    if (at >= 0 && line[at] !== v) return null;
  }
  const idx = headers.indexOf(column);
  return idx >= 0 && line[idx] !== undefined && line[idx] !== null ? String(line[idx]) : '';
};
// Values written back unchanged keep their original type, so a test run or an undo changes nothing.
const raw = (v) => (v === undefined || v === null ? '' : v);
const MS_PER_DAY = 86400000;
const SHEETS_EPOCH = 25569; // Google Sheets serial number of 1970-01-01

// Returns { y, m, d } or null. Accepts Google Sheets serial numbers and YYYY-MM-DD.
// Ambiguous text such as 03/04/2026 is rejected, never guessed.
function parseDate(v) {
  if (typeof v === 'number' && Number.isFinite(v)) {
    const dt = new Date(Math.round((v - SHEETS_EPOCH) * MS_PER_DAY));
    return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
  }
  const s = text(v);
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  const m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?=$|[T\s])/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const check = new Date(Date.UTC(y, mo - 1, d));
  if (check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) return null;
  return { y, m: mo, d };
}

// Returns minutes after midnight or null. Accepts 14:30, 2:30 PM and Sheets time values.
function parseTime(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - Math.floor(v)) * 1440) % 1440;
  const m = lower(v).match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2]);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return h > 23 || min > 59 ? null : h * 60 + min;
}

const dayNumber = (p) => Math.round(Date.UTC(p.y, p.m - 1, p.d) / MS_PER_DAY);
const pad = (n) => String(n).padStart(2, '0');
const formatDate = (p) => `${p.y}-${pad(p.m)}-${pad(p.d)}`;
const formatTime = (mins) => (mins === null ? '' : `${pad(Math.floor(mins / 60))}:${pad(mins % 60)}`);

// "Today" and "now" come from $now, which follows Workflow settings > Timezone.
// Nothing here depends on the timezone of the server running n8n.
const todayNumber = () => dayNumber({ y: $now.year, m: $now.month, d: $now.day });
const nowMinutes = () => todayNumber() * 1440 + $now.hour * 60 + $now.minute;
// Parses a timestamp written by this workflow (ISO 8601 with offset). Returns epoch ms or null.
function parseStamp(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - 25569) * 86400000);
  const ms = Date.parse(text(v));
  return Number.isFinite(ms) ? ms : null;
}
// ---- End of helpers ----

const cfg = $('Set Configuration Params').first().json;
const testMode = flag(cfg.testMode);
const perRound = Math.max(1, num(cfg.offersPerRound, 1));
const maxPerSlot = Math.max(1, num(cfg.maxOffersPerSlot, 5));
const claimMs = Math.max(0.25, num(cfg.claimWindowHours, 4)) * 3600000;
const maxDays = num(cfg.maxDaysAhead, 30);
const noticeMinutes = Math.max(0, num(cfg.minHoursNotice, 2)) * 60;
const nowMs = $now.toMillis();
const today = todayNumber();
const nowMin = nowMinutes();

const bookings = $('Read Booking Data').all();
const waitlist = $input.all();
const countBy = (items, tab, col) => {
  const c = {};
  for (const i of items) {
    const k = shownKey(tab, col, i.json);
    if (text(k)) c[k] = (c[k] || 0) + 1;
  }
  return c;
};
const bookingIds = countBy(bookings, 'Bookings', 'Booking ID');
const waitlistIds = countBy(waitlist, 'Waitlist', 'Waitlist ID');

// Test runs write nothing to the sheet, so each slot is test-offered at most once a day.
// This memory is kept between scheduled runs (manual runs always send).
const memory = $getWorkflowStaticData('global');
memory.testSlots = memory.testSlots || {};
for (const [k, at] of Object.entries(memory.testSlots)) if (nowMs - at > 86400000) delete memory.testSlots[k];

// 1. Open slots: cancelled, far enough ahead, and not inside an earlier offer's claim window.
const slots = [];
for (const b of bookings) {
  const r = b.json;
  if (lower(r['Status']) !== 'cancelled') continue;
  const key = shownKey('Bookings', 'Booking ID', r);
  const date = parseDate(r['Appointment Date']);
  if (!text(key) || bookingIds[key] > 1 || !date) continue; // listed by "Identify Rows for Correction"
  const daysAhead = dayNumber(date) - today;
  if (daysAhead < 0 || daysAhead > maxDays) continue;
  const time = parseTime(r['Appointment Time']);
  // Without a start time we cannot tell whether a same-day slot has passed, so it is skipped.
  if (time === null ? daysAhead < 1 : dayNumber(date) * 1440 + time - nowMin < noticeMinutes) continue;
  const offeredTo = list(r['Waitlist Offered To']).map((e) => e.toLowerCase());
  if (offeredTo.length >= maxPerSlot) continue;
  const lastOffer = parseStamp(r['Waitlist Offered At']);
  if (lastOffer !== null && nowMs - lastOffer < claimMs) continue; // the previous round is still open
  if (testMode && memory.testSlots[key]) continue; // already test-offered today
  slots.push({ key, service: text(r['Service']), date, time, offeredTo,
    before: { offeredTo: raw(r['Waitlist Offered To']), offeredAt: raw(r['Waitlist Offered At']) } });
}
slots.sort((a, b) => dayNumber(a.date) - dayNumber(b.date) || (a.time ?? 0) - (b.time ?? 0));

// 2. Waiting clients. Someone already offered a slot is eligible again once their claim window passes.
const waiting = [];
waitlist.forEach((item, index) => {
  const w = item.json;
  const key = shownKey('Waitlist', 'Waitlist ID', w);
  if (!text(key) || waitlistIds[key] > 1 || !isEmail(w['Client Email'])) return;
  const status = lower(w['Status']) || 'waiting';
  if (status === 'offered') {
    const at = parseStamp(w['Offered At']);
    if (at !== null && nowMs - at < claimMs) return;
  } else if (status !== 'waiting') {
    return; // booked, send failed, or anything else
  }
  const from = text(w['Earliest Date']) ? parseDate(w['Earliest Date']) : 'any';
  const to = text(w['Latest Date']) ? parseDate(w['Latest Date']) : 'any';
  if (from === null || to === null) return; // unreadable date range, listed by "Identify Rows for Correction"
  waiting.push({
    index, row: w, key, email: lower(w['Client Email']), service: lower(w['Service']), from, to,
    added: parseStamp(w['Added At']) ?? Number.MAX_SAFE_INTEGER,
  });
});
waiting.sort((a, b) => a.added - b.added); // longest waiting first

// 3. Offer each slot to the next people in line. Nobody gets two offers in one run.
const used = new Set();
const out = [];
for (const s of slots) {
  const day = dayNumber(s.date);
  const room = Math.min(perRound, maxPerSlot - s.offeredTo.length);
  const picks = waiting
    .filter((w) =>
      !used.has(w.email) &&
      !s.offeredTo.includes(w.email) &&
      (!w.service || w.service === lower(s.service)) &&
      (w.from === 'any' || day >= dayNumber(w.from)) &&
      (w.to === 'any' || day <= dayNumber(w.to)))
    .slice(0, room);
  const planned = [...new Set([...s.offeredTo, ...picks.map((w) => w.email)])];
  for (const w of picks) {
    used.add(w.email);
    out.push({
      json: {
        slotKey: s.key,
        service: s.service || 'appointment',
        appointmentDate: formatDate(s.date),
        appointmentTime: formatTime(s.time),
        peopleInRound: picks.length,
        offeredBefore: s.offeredTo.length,
        waitlistKey: w.key,
        clientName: text(w.row['Client Name']) || 'there',
        clientEmail: text(w.row['Client Email']),
        before: {
          status: raw(w.row['Status']),
          offeredSlot: raw(w.row['Offered Slot']),
          offeredAt: raw(w.row['Offered At']),
          error: raw(w.row['Offer Error']),
          slotOfferedTo: s.before.offeredTo,
          slotOfferedAt: s.before.offeredAt,
        },
        slotOfferedToPlanned: planned.join(','),
      },
      pairedItem: { item: w.index },
    });
  }
}
return out;

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
// ---- End of helpers ----

const cfg = $('Set Configuration Params').first().json;
const b = $json;
const when = b.appointmentTime ? `${b.appointmentDate} at ${b.appointmentTime}` : b.appointmentDate;
const others = b.peopleInRound - 1;
const hours = num(cfg.claimWindowHours, 4);

// Say exactly how the offer works. The slot is open on the booking page, so nobody is promised it.
const how = others > 0
  ? `We have also told ${others} other ${others === 1 ? 'person' : 'people'} on the waiting list.`
  : b.offeredBefore === 0 ? 'You are the first person on the waiting list we are telling.' : '';
const lines = [
  `Hi ${b.clientName},`, '',
  `You asked to hear when a ${b.service} slot opened up. One is free now: ${when}.`, '',
  `Book it here: ${cfg.bookingPageUrl}`, '',
  [how, 'The slot stays open on our booking page, so it goes to whoever books first.'].filter(Boolean).join(' '),
  `If it is still free in ${hours} hours, we will let the next person on the list know.`, '',
  'No longer need a slot? Just reply and we will take you off the list.', '',
  'Thanks,', cfg.businessName,
];

const testMode = flag(cfg.testMode);
const subject = `A ${b.service} slot just opened up on ${b.appointmentDate}`;
// What "Update Client Offered Status" and "Update Slot Offered Status" write before the email goes out. Test runs write the old values back.
const claim = testMode
  ? { ...b.before }
  : { ...b.before, status: 'offered', offeredSlot: b.slotKey, offeredAt: $now.toISO(), error: 'Sending - not confirmed yet',
      slotOfferedTo: b.slotOfferedToPlanned, slotOfferedAt: $now.toISO() };
return {
  json: {
    ...b,
    testMode,
    claim,
    to: testMode ? cfg.staffEmail : b.clientEmail,
    subject: testMode ? `[TEST for ${b.clientEmail}] ${subject}` : subject,
    body: lines.join('\n'),
  },
};

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
// ---- End of helpers ----

// The Gmail node only returns { id, threadId, labelIds } or { error }.
// Everything else is read from the email this result belongs to (paired item).
const email = $('Prepare Slot Offer Email').item.json;
const delivered = Boolean($json.id) && !$json.error;
const error = delivered ? '' : text($json.error) || 'Gmail did not return a message id';
// Test runs never change the sheet. A live run confirms a delivered email or undoes a failed one.
const live = !email.testMode;

if (delivered && !live) {
  // Remember test-offered slots for a day so an activated workflow left in test mode does not repeat them.
  const memory = $getWorkflowStaticData('global');
  memory.testSlots = memory.testSlots || {};
  memory.testSlots[email.slotKey] = $now.toMillis();
}
// Delivered: keep the claim. Failed: take this client out of the queue ("send failed") so the slot
// moves on to the next person instead of retrying an address that does not work.
const final = !live ? email.before
  : delivered ? { ...email.claim, error: '' }
  : { ...email.before, status: 'send failed', error };
return { json: { ...email, delivered, error, final } };

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const list = (v) => text(v).split(',').map((x) => x.trim()).filter(Boolean);
// ---- End of helpers ----

// One row per slot: the clients Gmail actually delivered to, so a failed offer is not counted.
const rows = $('Log Offer Outcome').all().map((i) => i.json);
const bySlot = new Map();
for (const r of rows) {
  if (!bySlot.has(r.slotKey)) {
    bySlot.set(r.slotKey, { slotKey: r.slotKey, offeredTo: new Set(list(r.before.slotOfferedTo)),
      before: r.before, delivered: false });
  }
  const s = bySlot.get(r.slotKey);
  if (r.delivered && !r.testMode) {
    s.offeredTo.add(r.clientEmail.toLowerCase());
    s.delivered = true;
  }
}
return [...bySlot.values()].map((s) => ({
  json: {
    slotKey: s.slotKey,
    // Nothing delivered for this slot: write back exactly what was there.
    offeredTo: s.delivered ? [...s.offeredTo].join(',') : s.before.slotOfferedTo,
    offeredAt: s.delivered ? $now.toISO() : s.before.slotOfferedAt,
  },
}));

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
// ---- End of helpers ----

const cfg = $('Set Configuration Params').first().json;
const rows = $('Log Offer Outcome').all().map((i) => i.json);
const sent = rows.filter((r) => r.delivered);
const failed = rows.filter((r) => !r.delivered);
const testMode = rows.some((r) => r.testMode);
const line = (r) => `- ${r.appointmentDate}${r.appointmentTime ? ' ' + r.appointmentTime : ''} | ${r.service} | ${r.clientName}`;

const parts = [];
if (testMode) {
  parts.push('TEST MODE IS ON: every email below went to you, not to clients, and the sheet was not changed.');
  parts.push('Turn testMode off in Set Configuration Params when you are ready.', '');
}
parts.push(`Sent: ${sent.length}   Failed: ${failed.length}`);

if (failed.length) parts.push('Clients whose offer was not delivered are set to "send failed" and skipped until you set them back to waiting.');
parts.push('', 'When someone books a slot: set their Waitlist Status to booked, set the cancelled row to filled, and add their booking as a new row.');
if (failed.length) {
  parts.push('', 'NOT DELIVERED:');
  for (const r of failed) parts.push(`${line(r)} | ${r.error}`);
}
if (sent.length) {
  parts.push('', 'Delivered:');
  for (const r of sent) parts.push(line(r));
}
parts.push('', `Dates and times use the workflow timezone (${$now.zoneName}). Change it under Workflow settings if this is wrong.`);

const prefix = (testMode ? '[TEST] ' : '') + (failed.length ? 'ACTION NEEDED: ' : '');
return [{
  json: {
    to: cfg.staffEmail,
    subject: `${prefix}${sent.length} slot offers sent, ${failed.length} not delivered`,
    body: parts.join('\n'),
  },
}];

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
// IDs are matched exactly as Google Sheets displays them. When results are written back, the Sheets
// update looks the row up by its displayed text, so this is the value that finds the row again
// (a number formatted as 1,001.00 is read as 1001 but found as "1,001.00").
const DISPLAYED = {};
for (const r of $('Fetch Spreadsheet Data').first().json.valueRanges || []) {
  DISPLAYED[String(r.range || '').replace(/'/g, '').split('!')[0]] = r.values || [];
}
// Returns null when the row moved between the two reads (sorted, inserted or deleted in between):
// a text cell shows exactly the same text in both reads, so any difference means it is not the same row.
// Such a row is left for the next run instead of risking a write to someone else's row.
const shownKey = (tab, column, row) => {
  const values = DISPLAYED[tab] || [];
  const headers = values[0] || [];
  const line = values[(row.row_number || 0) - 1];
  if (!line) return null;
  for (const [col, v] of Object.entries(row)) {
    if (typeof v !== 'string' || v === '') continue;
    const at = headers.indexOf(col);
    if (at >= 0 && line[at] !== v) return null;
  }
  const idx = headers.indexOf(column);
  return idx >= 0 && line[idx] !== undefined && line[idx] !== null ? String(line[idx]) : '';
};
// Values written back unchanged keep their original type, so a test run or an undo changes nothing.
const raw = (v) => (v === undefined || v === null ? '' : v);
const MS_PER_DAY = 86400000;
const SHEETS_EPOCH = 25569; // Google Sheets serial number of 1970-01-01

// Returns { y, m, d } or null. Accepts Google Sheets serial numbers and YYYY-MM-DD.
// Ambiguous text such as 03/04/2026 is rejected, never guessed.
function parseDate(v) {
  if (typeof v === 'number' && Number.isFinite(v)) {
    const dt = new Date(Math.round((v - SHEETS_EPOCH) * MS_PER_DAY));
    return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
  }
  const s = text(v);
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  const m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?=$|[T\s])/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const check = new Date(Date.UTC(y, mo - 1, d));
  if (check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) return null;
  return { y, m: mo, d };
}

// Returns minutes after midnight or null. Accepts 14:30, 2:30 PM and Sheets time values.
function parseTime(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - Math.floor(v)) * 1440) % 1440;
  const m = lower(v).match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2]);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return h > 23 || min > 59 ? null : h * 60 + min;
}

const dayNumber = (p) => Math.round(Date.UTC(p.y, p.m - 1, p.d) / MS_PER_DAY);
const pad = (n) => String(n).padStart(2, '0');
const formatDate = (p) => `${p.y}-${pad(p.m)}-${pad(p.d)}`;
const formatTime = (mins) => (mins === null ? '' : `${pad(Math.floor(mins / 60))}:${pad(mins % 60)}`);

// "Today" and "now" come from $now, which follows Workflow settings > Timezone.
// Nothing here depends on the timezone of the server running n8n.
const todayNumber = () => dayNumber({ y: $now.year, m: $now.month, d: $now.day });
const nowMinutes = () => todayNumber() * 1440 + $now.hour * 60 + $now.minute;
// ---- End of helpers ----

// Runs every 15 minutes, so the same list is sent at most once a day.
const cfg = $('Set Configuration Params').first().json;
const today = todayNumber();
const problems = [];
const rowNo = (item, index) => item.json.row_number ?? index + 2;
const dupes = (items, tab, col) => {
  const c = {};
  items.forEach((i) => { const k = shownKey(tab, col, i.json); if (text(k)) c[k] = (c[k] || 0) + 1; });
  return c;
};

const bookings = $('Read Booking Data').all();
const bookingIds = dupes(bookings, 'Bookings', 'Booking ID');
bookings.forEach((item, index) => {
  const r = item.json;
  if (lower(r['Status']) !== 'cancelled') return;
  const date = parseDate(r['Appointment Date']);
  if (date && dayNumber(date) < today) return;
  const issues = [];
  const k = shownKey('Bookings', 'Booking ID', r);
  if (k === null) return; // moved during this run, checked again next run
  if (!text(k)) issues.push('Booking ID is empty');
  else if (bookingIds[k] > 1) issues.push(`Booking ID "${k}" is used more than once`);
  if (!date) issues.push(`Appointment Date "${text(r['Appointment Date'])}" is not a date (use YYYY-MM-DD)`);
  if (issues.length) problems.push(`- Bookings row ${rowNo(item, index)}: ${issues.join('; ')}`);
});

const waitlist = $input.all();
const waitlistIds = dupes(waitlist, 'Waitlist', 'Waitlist ID');
waitlist.forEach((item, index) => {
  const w = item.json;
  const status = lower(w['Status']);
  if (status === 'send failed') {
    problems.push(`- Waitlist row ${rowNo(item, index)}: the last offer to ${text(w['Client Email'])} could not be delivered ` +
      `(${text(w['Offer Error']) || 'no details'}). Fix the address and set Status back to waiting.`);
    return;
  }
  if (text(w['Offer Error']) === 'Sending - not confirmed yet') {
    problems.push(`- Waitlist row ${rowNo(item, index)}: an offer was being sent but the result was never recorded. Check your Gmail Sent folder.`);
  }
  if (!['waiting', 'offered', ''].includes(status)) return;
  const issues = [];
  const k = shownKey('Waitlist', 'Waitlist ID', w);
  if (k === null) return; // moved during this run, checked again next run
  if (!text(k)) issues.push('Waitlist ID is empty');
  else if (waitlistIds[k] > 1) issues.push(`Waitlist ID "${k}" is used more than once`);
  if (!isEmail(w['Client Email'])) issues.push(`Client Email "${text(w['Client Email'])}" is not a valid address`);
  for (const col of ['Earliest Date', 'Latest Date']) {
    if (text(w[col]) && !parseDate(w[col])) issues.push(`${col} "${text(w[col])}" is not a date`);
  }
  if (issues.length) problems.push(`- Waitlist row ${rowNo(item, index)}: ${issues.join('; ')}`);
});

if (problems.length === 0) return [];

// Remember what was reported today (kept between scheduled runs, not manual test runs).
const memory = $getWorkflowStaticData('global');
const day = formatDate({ y: $now.year, m: $now.month, d: $now.day });
const signature = problems.join('\n');
if (memory.problemReportDay === day && memory.problemReportSignature === signature) return [];
memory.problemReportDay = day;
memory.problemReportSignature = signature;

return [{
  json: {
    to: cfg.staffEmail,
    subject: `${problems.length} waitlist or booking rows need your attention`,
    body: ['These rows are skipped until they are fixed:', '', ...problems].join('\n'),
  },
}];

// Runs in a separate execution started by the Error Trigger, where Set Configuration Params has not run.
// The .params of a node returns its configured values without running it.
const assignments = ($('Set Configuration Params').params.assignments || {}).assignments || [];
const setting = (name) => String((assignments.find((a) => a.name === name) || {}).value ?? '').trim();
const to = setting('staffEmail');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to) || /@example\.com$/i.test(to)) return []; // no real address to alert yet

const e = $input.first().json;
const execution = e.execution || {};
const name = (e.workflow && e.workflow.name) || 'n8n workflow';
const message = (execution.error && execution.error.message) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'unknown';
// Manual runs never start this branch, so mode "manual" can only be the editor's sample data.
if (execution.mode === 'manual' || message === 'Example Error Message') return [];

// The same failure is reported at most once every 6 hours, so a workflow that keeps failing
// every 15 minutes does not flood the inbox.
const memory = $getWorkflowStaticData('global');
const key = `${execution.lastNodeExecuted || ''}|${message}`;
const nowMs = Date.now();
memory.failureAlerts = memory.failureAlerts || {};
for (const [k, at] of Object.entries(memory.failureAlerts)) if (nowMs - at > 6 * 3600000) delete memory.failureAlerts[k];
if (memory.failureAlerts[key]) return [];
memory.failureAlerts[key] = nowMs;
const lines = [
  `"${name}" stopped before it finished.`,
  '',
  `Step: ${execution.lastNodeExecuted || 'unknown'}`,
  `Error: ${message}`,
];
if (execution.url) lines.push(`Details: ${execution.url}`);
lines.push('',
  'Emails sent before this step are not sent again. If it stopped while recording results, some rows',
  'may show "Sending - not confirmed yet": check your Gmail Sent folder for those clients.',
  'The same failure is reported at most once every 6 hours. Fix it and the next run carries on.');
return [{ json: { to, subject: `Workflow stopped: ${name}`, body: lines.join('\n') } }];
